parameters.jsonBody:
={
  "model": "llama3.2:1b",
  "stream": false,
  "options": {"temperature": 0},
  "messages": [
    {
      "role": "system",
      "content": "You classify a person's technology skill list into exactly one category: automation-heavy, web dev, or data. automation-heavy means tools like n8n, Zapier, Selenium, web scraping, workflow or API automation. web dev means React, JavaScript, FastAPI, MySQL, front-end or back-end web app building. data means Pandas, MongoDB, SQL, LangChain, data pipeline or ML-adjacent skills. Reply with ONLY the category label and nothing else, no punctuation."
    },
    {
      "role": "user",
      "content": "Name: {{$json.full_name}}. Skills: {{$json.skills}}. Which category fits best?"
    }
  ]
}

parameters.jsCode:
const raw = ($json.message && $json.message.content) || "";
// Small local models don't always reproduce "web dev" with the exact
// space/dash the prompt used (seen "webdev" in testing) -- collapse to
// letters-only before matching so spacing/punctuation variants all map
// to the same canonical label instead of silently falling through.
const collapse = (s) => s.toLowerCase().replace(/[^a-z]/g, "");
const CATEGORY_MAP = {
  automationheavy: "automation-heavy",
  webdev: "web dev",
  data: "data",
};
const category = CATEGORY_MAP[collapse(raw)] || "data";

const person = $("Fetch People Needing Tags").item.json;

return {
  json: {
    person_id: person.person_id,
    full_name: person.full_name,
    skills: person.skills,
    skill_category: category,
    raw_llm_response: raw
  }
};
